    faqList: {"faq-1":{"question":"Jagdamb Global Trade என்றால் என்ன?","answer":"ஜக்தாம்ப் குளோபல் டிரேட் என்பது 2025 ஆம் ஆண்டில் நிறுவப்பட்ட இந்தியாவை அடிப்படையாகக் கொண்ட ஏற்றுமதி-இறக்குமதி நிறுவனமாகும், இது விவசாய பொருட்கள், இயற்கை சூப்பர்ஃபுட்கள், உணவு பொருட்கள் மற்றும் சர்வதேச வர்த்தகத்திற்கான பிற தயாரிப்புகளில் கவனம் செலுத்துகிறது."},"faq-2":{"question":"Jagdamb உலகளாவிய வர்த்தகம் எங்கு உள்ளது?","answer":"ஜக்தாம்ப் குளோபல் டிரேட் இந்தியாவின் மகாராஷ்டிராவில் உள்ள தாராஷிவ் மாவட்டத்தில் உள்ள டிகோல் வஸ்தி, கல்லம் ஆகிய இடங்களில் அமைந்துள்ளது."},"faq-3":{"question":"நீங்கள் என்ன தயாரிப்புகளை வழங்குகிறீர்கள்?","answer":"எங்கள் வரம்பில் இயற்கையான சூப்பர்ஃபுட்கள், தாவரவியல் பொருட்கள், விவசாய பொருட்கள், உணவுப் பொருட்கள், மசாலாப் பொருட்கள், பழங்கள், காய்கறிகள், காபி, தேநீர், முந்திரி, சோளம், கோதுமை மற்றும் பதப்படுத்தப்பட்ட உணவுப் பொருட்கள் ஆகியவை அடங்கும்."},"faq-4":{"question":"ஏற்றுமதிக்கு பொருட்களை மொத்தமாக வழங்குகிறீர்களா?","answer":"எங்கள் பட்டியல் மொத்த மற்றும் ஏற்றுமதி விசாரணைகளை சுற்றி வடிவமைக்கப்பட்டுள்ளது.ஒவ்வொரு தயாரிப்புக்கும் கிடைக்கும், அளவு, பேக்கேஜிங் மற்றும் தேவைகள் பற்றி விவாதிக்கலாம்."},"faq-5":{"question":"பட்டியலிடப்படாத தயாரிப்பை நான் கோரலாமா?","answer":"ஆம்.வாங்குபவர்கள் குறிப்பிட்ட தயாரிப்புத் தேவைகளுடன் குழுவைத் தொடர்புகொண்டு விவாதத்தை ஆதாரமாகக் கொள்ளலாம்."},"faq-6":{"question":"நீங்கள் பேக்கேஜிங் தீர்வுகளை வழங்குகிறீர்களா?","answer":"பேக்கேஜிங் தீர்வுகள் ஜக்தாம்ப் குளோபல் டிரேடின் வளர்ந்து வரும் திறன்களின் ஒரு பகுதியாகும், மேலும் தயாரிப்பு மற்றும் வாங்குபவரின் தேவைகளுக்கு ஏற்ப விவாதிக்கப்படலாம்."},"faq-7":{"question":"ஒரு தயாரிப்பைப் பற்றி நான் எப்படி விசாரிக்க முடியும்?","answer":"தயாரிப்பு அட்டையில் இப்போது விசாரிக்கவும் பொத்தானைப் பயன்படுத்தவும் அல்லது WhatsApp மூலம் வணிகத்தைத் தொடர்பு கொள்ளவும்."},"faq-8":{"question":"ஜக்தாம்ப் குளோபல் டிரேடுடன் நான் எவ்வாறு தொடர்பு கொள்வது?","answer":"WhatsApp: +91 86684 04068 |மின்னஞ்சல்: அதிகாரப்பூர்வ வணிக மின்னஞ்சல்"},"faq-9":{"question":"சர்வதேச வாங்குபவர்கள் உங்களை தொடர்பு கொள்ள முடியுமா?","answer":"ஆம்.சர்வதேச வாங்குபவர்கள் தயாரிப்பு, அளவு, பேக்கேஜிங் மற்றும் இலக்கு தேவைகளுடன் Jagdamb Global Trade ஐ தொடர்பு கொள்ளலாம்."},"faq-10":{"question":"ஒரு விசாரணையில் நான் என்ன தகவலைச் சேர்க்க வேண்டும்?","answer":"தயாரிப்பின் பெயர், அளவு, பேக்கேஜிங் விருப்பம், சேருமிடம் மற்றும் ஏதேனும் குறிப்பிட்ட தேவைகள் ஆகியவற்றைச் சேர்க்கவும்."},"faq-11":{"question":"தயாரிப்புகள் இந்தியாவில் இருந்து பெறப்பட்டதா?","answer":"Jagdamb Global Trade என்பது இந்தியாவை தளமாகக் கொண்ட ஒரு ஏற்றுமதி-இறக்குமதி நிறுவனமாகும், மேலும் அதன் பட்டியல் சர்வதேச வர்த்தகத்திற்காக இந்தியாவில் இருந்து பெறப்படும் தயாரிப்புகளை மையமாகக் கொண்டுள்ளது."},"faq-12":{"question":"நான் எப்படி மேற்கோளைப் பெறுவது?","answer":"தயாரிப்பு, அளவு, பேக்கேஜிங் மற்றும் சேருமிடத் தகவலுடன் விசாரணையைச் சமர்ப்பிக்கவும்."},"faq-13":{"question":"தனிப்பயனாக்கப்பட்ட தேவைகளை நான் விவாதிக்கலாமா?","answer":"ஆம்.வாங்குபவர்கள் குறிப்பிட்ட தயாரிப்பு, அளவு, பேக்கேஜிங் மற்றும் வர்த்தகத் தேவைகளைப் பகிர்ந்து கொள்ளலாம்."},"faq-14":{"question":"நீண்ட கால வணிக உறவுகளுக்கு Jagdamb Global Trade கிடைக்குமா?","answer":"Jagdamb Global Trade வாங்குவோர் மற்றும் வணிக கூட்டாளர்களுடன் நம்பகமான, நீண்ட கால உறவுகளை உருவாக்குவதை நோக்கமாகக் கொண்டுள்ளது."},"faq-15":{"question":"எனது விசாரணைக்கு எவ்வளவு விரைவாக பதிலளிக்கப்படும்?","answer":"விசாரணையின் தயாரிப்பு மற்றும் சிக்கலான தன்மையைப் பொறுத்து பதில் நேரம் மாறுபடலாம்.முழுமையான விசாரணைகள் குழுவின் தேவைகளை திறமையாக புரிந்துகொள்ள உதவுகிறது."}},
