    faqList: {"faq-1":{"question":"ಜಗದಂಬ್ ಗ್ಲೋಬಲ್ ಟ್ರೇಡ್ ಎಂದರೇನು?","answer":"ಜಗದಂಬ್ ಗ್ಲೋಬಲ್ ಟ್ರೇಡ್ 2025 ರಲ್ಲಿ ಸ್ಥಾಪನೆಯಾದ ಭಾರತ ಮೂಲದ ರಫ್ತು-ಆಮದು ಸಂಸ್ಥೆಯಾಗಿದ್ದು, ಕೃಷಿ ಉತ್ಪನ್ನಗಳು, ನೈಸರ್ಗಿಕ ಸೂಪರ್‌ಫುಡ್‌ಗಳು, ಆಹಾರ ಪದಾರ್ಥಗಳು ಮತ್ತು ಅಂತರರಾಷ್ಟ್ರೀಯ ವ್ಯಾಪಾರಕ್ಕಾಗಿ ಇತರ ಉತ್ಪನ್ನಗಳ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸಿದೆ."},"faq-2":{"question":"ಜಗದಂಬ್ ಗ್ಲೋಬಲ್ ಟ್ರೇಡ್ ಎಲ್ಲಿದೆ?","answer":"ಜಗದಂಬ್ ಗ್ಲೋಬಲ್ ಟ್ರೇಡ್ ಡಿಘೋಲ್ ವಸ್ತಿ, ಕಲ್ಲಂ, ಜಿಲ್ಲೆಯ ಧಾರಾಶಿವ್, ಮಹಾರಾಷ್ಟ್ರ, ಭಾರತದಲ್ಲಿ ನೆಲೆಗೊಂಡಿದೆ."},"faq-3":{"question":"ನೀವು ಯಾವ ಉತ್ಪನ್ನಗಳನ್ನು ನೀಡುತ್ತೀರಿ?","answer":"ನಮ್ಮ ಶ್ರೇಣಿಯು ನೈಸರ್ಗಿಕ ಸೂಪರ್‌ಫುಡ್‌ಗಳು, ಸಸ್ಯಶಾಸ್ತ್ರೀಯ ಪದಾರ್ಥಗಳು, ಕೃಷಿ ಉತ್ಪನ್ನಗಳು, ಆಹಾರ ಉತ್ಪನ್ನಗಳು, ಮಸಾಲೆಗಳು, ಹಣ್ಣುಗಳು, ತರಕಾರಿಗಳು, ಕಾಫಿ, ಚಹಾ, ಗೋಡಂಬಿ, ಮೆಕ್ಕೆಜೋಳ, ಗೋಧಿ ಮತ್ತು ಸಂಸ್ಕರಿಸಿದ ಆಹಾರ ಉತ್ಪನ್ನಗಳನ್ನು ಒಳಗೊಂಡಿದೆ."},"faq-4":{"question":"ರಫ್ತು ಮಾಡಲು ನೀವು ಉತ್ಪನ್ನಗಳನ್ನು ದೊಡ್ಡ ಪ್ರಮಾಣದಲ್ಲಿ ನೀಡುತ್ತೀರಾ?","answer":"ನಮ್ಮ ಕ್ಯಾಟಲಾಗ್ ಅನ್ನು ಬೃಹತ್ ಮತ್ತು ರಫ್ತು ವಿಚಾರಣೆಗಳ ಸುತ್ತಲೂ ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿದೆ.ಪ್ರತಿ ಉತ್ಪನ್ನಕ್ಕೆ ಲಭ್ಯತೆ, ಪ್ರಮಾಣ, ಪ್ಯಾಕೇಜಿಂಗ್ ಮತ್ತು ಅವಶ್ಯಕತೆಗಳನ್ನು ಚರ್ಚಿಸಬಹುದು."},"faq-5":{"question":"ಪಟ್ಟಿ ಮಾಡದ ಉತ್ಪನ್ನವನ್ನು ನಾನು ವಿನಂತಿಸಬಹುದೇ?","answer":"ಹೌದು.ಖರೀದಿದಾರರು ಸೋರ್ಸಿಂಗ್ ಚರ್ಚೆಗಾಗಿ ನಿರ್ದಿಷ್ಟ ಉತ್ಪನ್ನದ ಅವಶ್ಯಕತೆಗಳೊಂದಿಗೆ ತಂಡವನ್ನು ಸಂಪರ್ಕಿಸಬಹುದು."},"faq-6":{"question":"ನೀವು ಪ್ಯಾಕೇಜಿಂಗ್ ಪರಿಹಾರಗಳನ್ನು ಒದಗಿಸುತ್ತೀರಾ?","answer":"ಪ್ಯಾಕೇಜಿಂಗ್ ಪರಿಹಾರಗಳು ಜಗದಂಬ್ ಗ್ಲೋಬಲ್ ಟ್ರೇಡ್‌ನ ಬೆಳೆಯುತ್ತಿರುವ ಸಾಮರ್ಥ್ಯಗಳ ಭಾಗವಾಗಿದೆ ಮತ್ತು ಉತ್ಪನ್ನ ಮತ್ತು ಖರೀದಿದಾರರ ಅಗತ್ಯತೆಗಳ ಪ್ರಕಾರ ಚರ್ಚಿಸಬಹುದು."},"faq-7":{"question":"ಉತ್ಪನ್ನದ ಬಗ್ಗೆ ನಾನು ಹೇಗೆ ವಿಚಾರಿಸಬಹುದು?","answer":"ಉತ್ಪನ್ನ ಕಾರ್ಡ್‌ನಲ್ಲಿ ಈಗ ವಿಚಾರಣೆ ಬಟನ್ ಬಳಸಿ ಅಥವಾ WhatsApp ಮೂಲಕ ವ್ಯಾಪಾರವನ್ನು ಸಂಪರ್ಕಿಸಿ."},"faq-8":{"question":"ಜಗದಂಬ್ ಗ್ಲೋಬಲ್ ಟ್ರೇಡ್ ಅನ್ನು ನಾನು ಹೇಗೆ ಸಂಪರ್ಕಿಸಬಹುದು?","answer":"WhatsApp: +91 86684 04068 |ಇಮೇಲ್: ಅಧಿಕೃತ ವ್ಯಾಪಾರ ಇಮೇಲ್"},"faq-9":{"question":"ಅಂತರಾಷ್ಟ್ರೀಯ ಖರೀದಿದಾರರು ನಿಮ್ಮನ್ನು ಸಂಪರ್ಕಿಸಬಹುದೇ?","answer":"ಹೌದು.ಅಂತಾರಾಷ್ಟ್ರೀಯ ಖರೀದಿದಾರರು ಉತ್ಪನ್ನ, ಪ್ರಮಾಣ, ಪ್ಯಾಕೇಜಿಂಗ್ ಮತ್ತು ಗಮ್ಯಸ್ಥಾನದ ಅಗತ್ಯತೆಗಳೊಂದಿಗೆ ಜಗದಂಬ್ ಗ್ಲೋಬಲ್ ಟ್ರೇಡ್ ಅನ್ನು ಸಂಪರ್ಕಿಸಬಹುದು."},"faq-10":{"question":"ವಿಚಾರಣೆಯಲ್ಲಿ ನಾನು ಯಾವ ಮಾಹಿತಿಯನ್ನು ಸೇರಿಸಬೇಕು?","answer":"ಉತ್ಪನ್ನದ ಹೆಸರು, ಪ್ರಮಾಣ, ಪ್ಯಾಕೇಜಿಂಗ್ ಆದ್ಯತೆ, ಗಮ್ಯಸ್ಥಾನ ಮತ್ತು ಯಾವುದೇ ನಿರ್ದಿಷ್ಟ ಅವಶ್ಯಕತೆಗಳನ್ನು ಸೇರಿಸಿ."},"faq-11":{"question":"ಉತ್ಪನ್ನಗಳನ್ನು ಭಾರತದಿಂದ ಪಡೆಯಲಾಗಿದೆಯೇ?","answer":"ಜಗದಂಬ್ ಗ್ಲೋಬಲ್ ಟ್ರೇಡ್ ಭಾರತ-ಆಧಾರಿತ ರಫ್ತು-ಆಮದು ಸಂಸ್ಥೆಯಾಗಿದೆ ಮತ್ತು ಅದರ ಕ್ಯಾಟಲಾಗ್ ಅಂತರರಾಷ್ಟ್ರೀಯ ವ್ಯಾಪಾರಕ್ಕಾಗಿ ಭಾರತದಿಂದ ಮೂಲದ ಉತ್ಪನ್ನಗಳ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸುತ್ತದೆ."},"faq-12":{"question":"ನಾನು ಉದ್ಧರಣವನ್ನು ಹೇಗೆ ಪಡೆಯುವುದು?","answer":"ಉತ್ಪನ್ನ, ಪ್ರಮಾಣ, ಪ್ಯಾಕೇಜಿಂಗ್ ಮತ್ತು ಗಮ್ಯಸ್ಥಾನದ ಮಾಹಿತಿಯೊಂದಿಗೆ ವಿಚಾರಣೆಯನ್ನು ಸಲ್ಲಿಸಿ."},"faq-13":{"question":"ನಾನು ಕಸ್ಟಮೈಸ್ ಮಾಡಿದ ಅವಶ್ಯಕತೆಗಳನ್ನು ಚರ್ಚಿಸಬಹುದೇ?","answer":"ಹೌದು.ಖರೀದಿದಾರರು ನಿರ್ದಿಷ್ಟ ಉತ್ಪನ್ನ, ಪ್ರಮಾಣ, ಪ್ಯಾಕೇಜಿಂಗ್ ಮತ್ತು ವ್ಯಾಪಾರದ ಅವಶ್ಯಕತೆಗಳನ್ನು ಹಂಚಿಕೊಳ್ಳಬಹುದು."},"faq-14":{"question":"ದೀರ್ಘಾವಧಿಯ ವ್ಯಾಪಾರ ಸಂಬಂಧಗಳಿಗಾಗಿ ಜಗದಂಬ್ ಗ್ಲೋಬಲ್ ಟ್ರೇಡ್ ಲಭ್ಯವಿದೆಯೇ?","answer":"ಜಗದಂಬ್ ಗ್ಲೋಬಲ್ ಟ್ರೇಡ್ ಖರೀದಿದಾರರು ಮತ್ತು ವ್ಯಾಪಾರ ಪಾಲುದಾರರೊಂದಿಗೆ ವಿಶ್ವಾಸಾರ್ಹ, ದೀರ್ಘಾವಧಿಯ ಸಂಬಂಧಗಳನ್ನು ನಿರ್ಮಿಸುವ ಗುರಿಯನ್ನು ಹೊಂದಿದೆ."},"faq-15":{"question":"ನನ್ನ ವಿಚಾರಣೆಗೆ ಎಷ್ಟು ಬೇಗನೆ ಉತ್ತರಿಸಲಾಗುವುದು?","answer":"ಉತ್ಪನ್ನ ಮತ್ತು ವಿಚಾರಣೆಯ ಸಂಕೀರ್ಣತೆಯನ್ನು ಅವಲಂಬಿಸಿ ಪ್ರತಿಕ್ರಿಯೆ ಸಮಯ ಬದಲಾಗಬಹುದು.ಸಂಪೂರ್ಣ ವಿಚಾರಣೆಗಳು ತಂಡವು ಅವಶ್ಯಕತೆಗಳನ್ನು ಸಮರ್ಥವಾಗಿ ಅರ್ಥಮಾಡಿಕೊಳ್ಳಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ."}},
