    productsList: {"moringa-powder":{"name":"مورنگا پاؤڈر","description":"خالص، سایہ میں خشک نامیاتی Moringa oleifera لیف پاؤڈر بڑے پیمانے پر عالمی برآمد کے لیے پریمیم ہندوستانی فارموں سے حاصل کیا جاتا ہے۔"},"turmeric-powder":{"name":"ہلدی پاؤڈر","description":"متحرک گولڈن کرکوما لونگا پاؤڈر جس میں قدرتی کرکومین مواد زیادہ ہے، جو کھانے کے اجزاء اور تندرستی کے فارمولیشنز کے لیے مثالی ہے۔"},"fingertail-millet":{"name":"انگلی جوار","description":"غذائیت سے بھرپور، آب و ہوا کے لیے لچکدار انڈین فنگر ٹیل باجرا، بین الاقوامی تجارت اور استعمال کے لیے احتیاط سے صاف اور ترتیب دیا گیا ہے۔"},"cow-dung":{"name":"گائے کا گوبر","description":"100% قدرتی، دھوپ میں خشک ہندوستانی گائے کے گوبر کے کیک اور کھاد، جو روایتی طور پر نامیاتی کاشتکاری، کھادوں اور رسمی مقاصد کے لیے تیار کیے جاتے ہیں۔"}},
    faqList: {"faq-1":{"question":"جگدمب عالمی تجارت کیا ہے؟","answer":"Jagdamb Global Trade ایک ہندوستان میں قائم برآمدی درآمدی فرم ہے جس کی بنیاد 2025 میں رکھی گئی تھی، جس کی توجہ بین الاقوامی تجارت کے لیے زرعی مصنوعات، قدرتی سپر فوڈز، کھانے کے اجزاء اور دیگر مصنوعات پر مرکوز ہے۔"},"faq-2":{"question":"جگدمب گلوبل ٹریڈ کہاں ہے؟","answer":"جگدمب گلوبل ٹریڈ دیگھول وستی، کلم، ضلع دھاراشیو، مہاراشٹر، بھارت میں واقع ہے۔"},"faq-3":{"question":"آپ کونسی مصنوعات پیش کرتے ہیں؟","answer":"ہماری رینج میں قدرتی سپر فوڈز، نباتاتی اجزاء، زرعی مصنوعات، کھانے کی مصنوعات، مصالحے، پھل، سبزیاں، کافی، چائے، کاجو، مکئی، گندم، اور پراسیسڈ فوڈ پروڈکٹس شامل ہیں۔"},"faq-4":{"question":"کیا آپ برآمد کے لیے بڑی تعداد میں مصنوعات پیش کرتے ہیں؟","answer":"ہمارا کیٹلاگ بلک اور ایکسپورٹ انکوائریوں کے ارد گرد ڈیزائن کیا گیا ہے۔ہر پروڈکٹ کے لیے دستیابی، مقدار، پیکیجنگ اور ضروریات پر تبادلہ خیال کیا جا سکتا ہے۔"},"faq-5":{"question":"کیا میں ایسے پروڈکٹ کی درخواست کر سکتا ہوں جو درج نہیں ہے؟","answer":"جی ہاںخریدار سوسنگ ڈسکشن کے لیے مخصوص مصنوعات کی ضروریات کے ساتھ ٹیم سے رابطہ کر سکتے ہیں۔"},"faq-6":{"question":"کیا آپ پیکیجنگ حل فراہم کرتے ہیں؟","answer":"پیکیجنگ سلوشنز جگدمب گلوبل ٹریڈ کی بڑھتی ہوئی صلاحیتوں کا حصہ ہیں اور پروڈکٹ اور خریدار کی ضروریات کے مطابق بات چیت کی جا سکتی ہے۔"},"faq-7":{"question":"میں کسی پروڈکٹ کے بارے میں کیسے پوچھ سکتا ہوں؟","answer":"پروڈکٹ کارڈ پر انکوائر ناؤ بٹن استعمال کریں یا واٹس ایپ کے ذریعے کاروبار سے رابطہ کریں۔"},"faq-8":{"question":"میں جگدمب گلوبل ٹریڈ سے کیسے رابطہ کر سکتا ہوں؟","answer":"واٹس ایپ: +91 86684 04068 |ای میل: سرکاری کاروباری ای میل"},"faq-9":{"question":"کیا بین الاقوامی خریدار آپ سے رابطہ کر سکتے ہیں؟","answer":"جی ہاںبین الاقوامی خریدار مصنوعات، مقدار، پیکیجنگ، اور منزل کی ضروریات کے ساتھ جگدمب گلوبل ٹریڈ سے رابطہ کر سکتے ہیں۔"},"faq-10":{"question":"مجھے انکوائری میں کون سی معلومات شامل کرنی چاہیے؟","answer":"پروڈکٹ کا نام، مقدار، پیکیجنگ کی ترجیح، منزل، اور کوئی مخصوص ضروریات شامل کریں۔"},"faq-11":{"question":"کیا مصنوعات ہندوستان سے منگوائی جاتی ہیں؟","answer":"جگدمب گلوبل ٹریڈ ایک ہندوستان میں قائم برآمدی درآمدی فرم ہے اور اس کا کیٹلاگ بین الاقوامی تجارت کے لیے ہندوستان سے حاصل کردہ مصنوعات پر مرکوز ہے۔"},"faq-12":{"question":"میں کوٹیشن کیسے حاصل کروں؟","answer":"مصنوعات، مقدار، پیکیجنگ، اور منزل کی معلومات کے ساتھ انکوائری جمع کروائیں۔"},"faq-13":{"question":"کیا میں اپنی مرضی کے مطابق ضروریات پر بات کر سکتا ہوں؟","answer":"جی ہاںخریدار مخصوص مصنوعات، مقدار، پیکیجنگ، اور تجارتی ضروریات کا اشتراک کر سکتے ہیں۔"},"faq-14":{"question":"کیا جگدمب گلوبل ٹریڈ طویل مدتی کاروباری تعلقات کے لیے دستیاب ہے؟","answer":"جگدمب گلوبل ٹریڈ کا مقصد خریداروں اور کاروباری شراکت داروں کے ساتھ قابل اعتماد، طویل مدتی تعلقات استوار کرنا ہے۔"},"faq-15":{"question":"کتنی جلدی میری انکوائری کا جواب دیا جائے گا؟","answer":"انکوائری کی مصنوعات اور پیچیدگی کے لحاظ سے ردعمل کا وقت مختلف ہو سکتا ہے۔مکمل پوچھ گچھ ٹیم کو ضروریات کو مؤثر طریقے سے سمجھنے میں مدد کرتی ہے۔"}},
