    faqList: {"faq-1":{"question":"Apa itu Perdagangan Global Jagdamba?","answer":"Jagdamb Global Trade adalah perusahaan ekspor-impor yang berbasis di India yang didirikan pada tahun 2025, berfokus pada produk pertanian, makanan super alami, bahan makanan, dan produk lainnya untuk perdagangan internasional."},"faq-2":{"question":"Di mana Perdagangan Global Jagdamba berbasis?","answer":"Perdagangan Global Jagdamb berbasis di Dighol Vasti, Kallam, Distrik Dharashiv, Maharashtra, India."},"faq-3":{"question":"Produk apa yang Anda tawarkan?","answer":"Produk kami meliputi makanan super alami, bahan tumbuhan, produk pertanian, produk makanan, rempah-rempah, buah-buahan, sayuran, kopi, teh, kacang mete, jagung, gandum, dan produk makanan olahan."},"faq-4":{"question":"Apakah Anda menawarkan produk dalam jumlah besar untuk diekspor?","answer":"Katalog kami dirancang untuk pertanyaan massal dan ekspor.Ketersediaan, kuantitas, kemasan, dan persyaratan dapat didiskusikan untuk setiap produk."},"faq-5":{"question":"Bolehkah saya meminta produk yang tidak tercantum?","answer":"Ya.Pembeli dapat menghubungi tim dengan persyaratan produk spesifik untuk diskusi sumber."},"faq-6":{"question":"Apakah Anda menyediakan solusi pengemasan?","answer":"Solusi pengemasan adalah bagian dari kemampuan Jagdamba Global Trade yang berkembang dan dapat didiskusikan sesuai dengan kebutuhan produk dan pembeli."},"faq-7":{"question":"Bagaimana saya bisa menanyakan tentang suatu produk?","answer":"Gunakan tombol Tanya Sekarang pada kartu produk atau hubungi bisnis melalui WhatsApp."},"faq-8":{"question":"Bagaimana saya bisa menghubungi Jagdamba Global Trade?","answer":"WhatsApp: +91 86684 04068 |Email: Email Bisnis Resmi"},"faq-9":{"question":"Bisakah pembeli internasional menghubungi Anda?","answer":"Ya.Pembeli internasional dapat menghubungi Jagdamba Global Trade dengan persyaratan produk, kuantitas, kemasan, dan tujuan."},"faq-10":{"question":"Informasi apa yang harus saya sertakan dalam pertanyaan?","answer":"Cantumkan nama produk, jumlah, preferensi kemasan, tujuan, dan persyaratan spesifik apa pun."},"faq-11":{"question":"Apakah produknya bersumber dari India?","answer":"Jagdamb Global Trade adalah perusahaan ekspor-impor yang berbasis di India dan katalognya berfokus pada produk-produk yang bersumber dari India untuk perdagangan internasional."},"faq-12":{"question":"Bagaimana cara mendapatkan penawaran?","answer":"Kirimkan pertanyaan dengan informasi produk, kuantitas, kemasan, dan tujuan."},"faq-13":{"question":"Bisakah saya mendiskusikan persyaratan khusus?","answer":"Ya.Pembeli dapat berbagi produk, kuantitas, kemasan, dan persyaratan perdagangan tertentu."},"faq-14":{"question":"Apakah Jagdamba Global Trade tersedia untuk hubungan bisnis jangka panjang?","answer":"Perdagangan Global Jagdamba bertujuan untuk membangun hubungan jangka panjang yang andal dengan pembeli dan mitra bisnis."},"faq-15":{"question":"Seberapa cepat pertanyaan saya akan dijawab?","answer":"Waktu respons dapat bervariasi tergantung pada produk dan kompleksitas pertanyaan.Pertanyaan lengkap membantu tim memahami persyaratan secara efisien."}},
