    productsList: {"moringa-powder":{"name":"Poudre de Moringa","description":"Poudre de feuilles de Moringa oleifera biologique pure et séchée à l'ombre provenant de fermes indiennes de première qualité pour l'exportation mondiale en vrac."},"turmeric-powder":{"name":"Poudre de curcuma","description":"Poudre de Curcuma longa dorée et vibrante à haute teneur naturelle en curcumine, idéale pour les ingrédients alimentaires et les formulations de bien-être."},"fingertail-millet":{"name":"Millet à queue courte","description":"Un millet indien nutritif et résistant au climat, soigneusement nettoyé et trié pour le commerce et la consommation internationaux."},"cow-dung":{"name":"Bouse de vache","description":"Gâteaux et fumier de bouse de vache indienne 100 % naturels et séchés au soleil, traditionnellement transformés pour l'agriculture biologique, les engrais et à des fins rituelles."}},
    faqList: {"faq-1":{"question":"Qu’est-ce que le commerce mondial Jagdamb ?","answer":"Jagdamb Global Trade est une société d'import-export basée en Inde, fondée en 2025, qui se concentre sur les produits agricoles, les superaliments naturels, les ingrédients alimentaires et d'autres produits destinés au commerce international."},"faq-2":{"question":"Où est basé Jagdamb Global Trade ?","answer":"Jagdamb Global Trade est basé à Dighol Vasti, Kallam, district de Dharashiv, Maharashtra, Inde."},"faq-3":{"question":"Quels produits proposez-vous ?","answer":"Notre gamme comprend des superaliments naturels, des ingrédients botaniques, des produits agricoles, des produits alimentaires, des épices, des fruits, des légumes, du café, du thé, des noix de cajou, du maïs, du blé et des produits alimentaires transformés."},"faq-4":{"question":"Proposez-vous des produits en vrac pour l’export ?","answer":"Notre catalogue est conçu autour des demandes de masse et d’exportation.La disponibilité, la quantité, l'emballage et les exigences peuvent être discutés pour chaque produit."},"faq-5":{"question":"Puis-je demander un produit qui n'est pas répertorié ?","answer":"Oui.Les acheteurs peuvent contacter l’équipe avec des exigences spécifiques en matière de produits pour discuter de l’approvisionnement."},"faq-6":{"question":"Fournissez-vous des solutions d’emballage ?","answer":"Les solutions d'emballage font partie des capacités croissantes de Jagdamb Global Trade et peuvent être discutées en fonction des exigences du produit et de l'acheteur."},"faq-7":{"question":"Comment puis-je me renseigner sur un produit ?","answer":"Utilisez le bouton Se renseigner maintenant sur une fiche produit ou contactez l'entreprise via WhatsApp."},"faq-8":{"question":"Comment puis-je contacter Jagdamb Global Trade ?","answer":"WhatsApp : +91 86684 04068 |E-mail : E-mail professionnel officiel"},"faq-9":{"question":"Les acheteurs internationaux peuvent-ils vous contacter ?","answer":"Oui.Les acheteurs internationaux peuvent contacter Jagdamb Global Trade avec les exigences en matière de produit, de quantité, d'emballage et de destination."},"faq-10":{"question":"Quelles informations dois-je inclure dans une demande ?","answer":"Incluez le nom du produit, la quantité, les préférences d’emballage, la destination et toute exigence spécifique."},"faq-11":{"question":"Les produits proviennent-ils d’Inde ?","answer":"Jagdamb Global Trade est une société d'import-export basée en Inde et son catalogue se concentre sur les produits provenant d'Inde destinés au commerce international."},"faq-12":{"question":"Comment obtenir un devis ?","answer":"Soumettez une demande avec des informations sur le produit, la quantité, l'emballage et la destination."},"faq-13":{"question":"Puis-je discuter des exigences personnalisées ?","answer":"Oui.Les acheteurs peuvent partager des exigences spécifiques en matière de produits, de quantités, d’emballage et de commerce."},"faq-14":{"question":"Jagdamb Global Trade est-il disponible pour des relations commerciales à long terme ?","answer":"Jagdamb Global Trade vise à établir des relations fiables et à long terme avec les acheteurs et les partenaires commerciaux."},"faq-15":{"question":"Dans combien de temps ma demande recevra-t-elle une réponse ?","answer":"Le délai de réponse peut varier en fonction du produit et de la complexité de la demande.Des demandes de renseignements complètes aident l’équipe à comprendre efficacement les exigences."}},
