    productsList: {"moringa-powder":{"name":"Polvo de moringa","description":"Polvo de hoja de Moringa oleifera orgánico, puro y secado a la sombra, procedente de granjas indias de primera calidad para exportación mundial a granel."},"turmeric-powder":{"name":"Cúrcuma en polvo","description":"Polvo de cúrcuma longa dorado vibrante con alto contenido de curcumina natural, ideal para ingredientes alimentarios y formulaciones de bienestar."},"fingertail-millet":{"name":"Mijo cola de dedo","description":"Mijo cola indio, nutritivo y resistente al clima, cuidadosamente limpio y clasificado para el comercio y el consumo internacional."},"cow-dung":{"name":"Estiércol de vaca","description":"Tortas y estiércol de vaca india 100% naturales, secados al sol, procesados tradicionalmente para agricultura orgánica, fertilizantes y fines rituales."}},
    faqList: {"faq-1":{"question":"¿Qué es el comercio global de Jagdamb?","answer":"Jagdamb Global Trade es una empresa de exportación e importación con sede en la India fundada en 2025, centrada en productos agrícolas, superalimentos naturales, ingredientes alimentarios y otros productos para el comercio internacional."},"faq-2":{"question":"¿Dónde tiene su sede Jagdamb Global Trade?","answer":"Jagdamb Global Trade tiene su sede en Dighol Vasti, Kallam, distrito de Dharashiv, Maharashtra, India."},"faq-3":{"question":"¿Qué productos ofrecen?","answer":"Nuestra gama incluye superalimentos naturales, ingredientes botánicos, productos agrícolas, productos alimenticios, especias, frutas, verduras, café, té, anacardos, maíz, trigo y productos alimenticios procesados."},"faq-4":{"question":"¿Ofrecen productos a granel para exportación?","answer":"Nuestro catálogo está diseñado en torno a consultas a granel y de exportación.Se pueden discutir la disponibilidad, la cantidad, el embalaje y los requisitos para cada producto."},"faq-5":{"question":"¿Puedo solicitar un producto que no aparece en la lista?","answer":"Sí.Los compradores pueden comunicarse con el equipo con requisitos específicos del producto para discutir el abastecimiento."},"faq-6":{"question":"¿Ofrecen soluciones de embalaje?","answer":"Las soluciones de embalaje son parte de las crecientes capacidades de Jagdamb Global Trade y pueden discutirse según los requisitos del producto y del comprador."},"faq-7":{"question":"¿Cómo puedo consultar sobre un producto?","answer":"Utilice el botón Consultar ahora en la tarjeta de un producto o comuníquese con la empresa a través de WhatsApp."},"faq-8":{"question":"¿Cómo puedo contactar con Jagdamb Global Trade?","answer":"WhatsApp: +91 86684 04068 |Correo electrónico: correo electrónico comercial oficial"},"faq-9":{"question":"¿Pueden los compradores internacionales ponerse en contacto con usted?","answer":"Sí.Los compradores internacionales pueden comunicarse con Jagdamb Global Trade con los requisitos de producto, cantidad, embalaje y destino."},"faq-10":{"question":"¿Qué información debo incluir en una consulta?","answer":"Incluya el nombre del producto, la cantidad, la preferencia de embalaje, el destino y cualquier requisito específico."},"faq-11":{"question":"¿Los productos provienen de la India?","answer":"Jagdamb Global Trade es una empresa de exportación e importación con sede en la India y su catálogo se centra en productos procedentes de la India para el comercio internacional."},"faq-12":{"question":"¿Cómo obtengo una cotización?","answer":"Envíe una consulta con información sobre el producto, la cantidad, el embalaje y el destino."},"faq-13":{"question":"¿Puedo discutir los requisitos personalizados?","answer":"Sí.Los compradores pueden compartir requisitos comerciales, de cantidad, de embalaje y de productos específicos."},"faq-14":{"question":"¿Jagdamb Global Trade está disponible para relaciones comerciales a largo plazo?","answer":"Jagdamb Global Trade tiene como objetivo construir relaciones confiables y de largo plazo con compradores y socios comerciales."},"faq-15":{"question":"¿Qué tan rápido será respondida mi consulta?","answer":"El tiempo de respuesta puede variar dependiendo del producto y complejidad de la consulta.Las consultas completas ayudan al equipo a comprender los requisitos de manera eficiente."}},
