    faqList: {"faq-1":{"question":"تجارت جهانی جگدامب چیست؟","answer":"Jagdamb Global Trade یک شرکت صادرات و واردات مستقر در هند است که در سال 2025 تأسیس شد و بر محصولات کشاورزی، ابرغذاهای طبیعی، مواد غذایی و سایر محصولات برای تجارت بین‌المللی تمرکز دارد."},"faq-2":{"question":"تجارت جهانی جاگدامب کجاست؟","answer":"تجارت جهانی جاگدامب در دیقول وستی، کالام، منطقه داراشیو، ماهاراشترا، هند مستقر است."},"faq-3":{"question":"چه محصولاتی را ارائه می دهید؟","answer":"طیف ما شامل ابر غذای طبیعی، مواد گیاهی، محصولات کشاورزی، محصولات غذایی، ادویه جات ترشی جات، میوه ها، سبزیجات، قهوه، چای، بادام هندی، ذرت، گندم و محصولات غذایی فرآوری شده است."},"faq-4":{"question":"آیا محصولات را به صورت عمده برای صادرات عرضه می کنید؟","answer":"کاتالوگ ما در مورد درخواست های عمده و صادرات طراحی شده است.در دسترس بودن، کمیت، بسته بندی و الزامات را می توان برای هر محصول مورد بحث قرار داد."},"faq-5":{"question":"آیا می توانم محصولی را درخواست کنم که در لیست نیست؟","answer":"بله.خریداران می توانند برای بحث در مورد منبع یابی با تیمی که شرایط خاص محصول را دارند تماس بگیرند."},"faq-6":{"question":"آیا راه حل های بسته بندی ارائه می دهید؟","answer":"راه حل های بسته بندی بخشی از قابلیت های رو به رشد Jagdamb Global Trade هستند و می توانند با توجه به نیازهای محصول و خریدار مورد بحث قرار گیرند."},"faq-7":{"question":"چگونه می توانم در مورد یک محصول پرس و جو کنم؟","answer":"از دکمه Inquire Now روی کارت محصول استفاده کنید یا از طریق واتس اپ با کسب و کار تماس بگیرید."},"faq-8":{"question":"چگونه می توانم با تجارت جهانی جاگدامب تماس بگیرم؟","answer":"واتس اپ: +91 86684 04068 |ایمیل: ایمیل تجاری رسمی"},"faq-9":{"question":"آیا خریداران بین المللی می توانند با شما تماس بگیرند؟","answer":"بله.خریداران بین‌المللی می‌توانند با تجارت جهانی جاگدامب در مورد محصول، مقدار، بسته‌بندی و الزامات مقصد تماس بگیرند."},"faq-10":{"question":"چه اطلاعاتی را باید در یک استعلام لحاظ کنم؟","answer":"نام محصول، مقدار، اولویت بسته بندی، مقصد، و هر گونه الزامات خاص را شامل شود."},"faq-11":{"question":"آیا محصولات از هند تهیه می شوند؟","answer":"Jagdamb Global Trade یک شرکت صادرات و واردات مستقر در هند است و کاتالوگ آن بر محصولاتی که از هند برای تجارت بین‌المللی تهیه می‌شوند تمرکز دارد."},"faq-12":{"question":"چگونه می توانم یک نقل قول دریافت کنم؟","answer":"یک استعلام با اطلاعات محصول، مقدار، بسته بندی و مقصد ارسال کنید."},"faq-13":{"question":"آیا می توانم در مورد نیازهای سفارشی صحبت کنم؟","answer":"بله.خریداران می توانند محصول، مقدار، بسته بندی و نیازهای تجاری خاص را به اشتراک بگذارند."},"faq-14":{"question":"آیا تجارت جهانی Jagdamb برای روابط تجاری بلند مدت در دسترس است؟","answer":"هدف تجارت جهانی Jagdamb ایجاد روابط قابل اعتماد و طولانی مدت با خریداران و شرکای تجاری است."},"faq-15":{"question":"چقدر سریع به درخواست من پاسخ داده می شود؟","answer":"زمان پاسخ ممکن است بسته به محصول و پیچیدگی پرس و جو متفاوت باشد.پرس و جوهای کامل به تیم کمک می کند تا نیازها را به طور موثر درک کند."}},
